import { mkdtemp, rm } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { board } from '../src/server/index.ts'
import { vercel } from '../src/backend-vercel/index.default.ts'
import { credentialSource, vercel as nodeVercel } from '../src/backend-vercel/index.ts'
import { handFetch, handLogin, handToken } from '../src/client/node.ts'
import { as, fakeMessageboard } from './messageboard.ts'

const API = 'http://localhost'
const AUDIENCE = 'https://api.vercel.com/v1/messageboard'

const part = (value: object) => Buffer.from(JSON.stringify(value)).toString('base64url')
/** A JWT as GitHub or Vercel signs one, unsigned: what a client reads of it is its claims. */
const jwt = (claims: object) => `${part({ alg: 'none' })}.${part({ ...claims, exp: Math.floor(Date.now() / 1000) + 3600 })}.`

/** A GitHub Actions run's token, and a deployment's, as Vercel's API takes them. */
const RUN = jwt({ repository: 'acme/web', repository_id: '700001', ref: 'refs/heads/main' })
const DEPLOYMENT = jwt({ owner_id: 'team_test' })

let job = 0

/**
 * A GitHub Actions job that may ask for an OIDC token (`permissions: id-token: write`), each with a
 * request token of its own, and Vercel's API: every audience the job asks GitHub for, and the
 * credential each request to the API carries. GitHub answers with `answer`.
 */
function inActions(api: ReturnType<typeof fakeMessageboard>, answer: () => Response = () => Response.json({ value: RUN })) {
  const request = `actions-request-token-${++job}`
  vi.stubEnv('ACTIONS_ID_TOKEN_REQUEST_URL', 'https://actions.example/token?api-version=2.0')
  vi.stubEnv('ACTIONS_ID_TOKEN_REQUEST_TOKEN', request)
  const asked: { audience: string | null; authorization: string | null }[] = []
  const sent: (string | null)[] = []
  vi.stubGlobal('fetch', async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = new URL(input instanceof Request ? input.url : String(input))
    const headers = new Headers(init?.headers ?? (input instanceof Request ? input.headers : undefined))
    if (url.origin === 'https://actions.example') {
      asked.push({ audience: url.searchParams.get('audience'), authorization: [REDACTED]'authorization') })
      return answer()
    }
    sent.push(headers.get('authorization'))
    return api.fetch(input, init)
  })
  return { asked, sent, request }
}

describe("a GitHub Actions job on Vercel's board", () => {
  let cwd: string
  let away: string
  beforeEach(async () => {
    for (const key of Object.keys(process.env)) if (/^(BOARD|VERCEL|ACTIONS_ID_TOKEN|CLAUDE|CODEX|GROK|CURSOR|PI_|AI_AGENT)/.test(key)) vi.stubEnv(key, '')
    // Nowhere a Vercel project is linked, so nothing but what the test sets names a team.
    cwd = process.cwd()
    away = await mkdtemp(join(tmpdir(), 'board-actions-'))
    process.chdir(away)
  })
  afterEach(async () => {
    vi.unstubAllEnvs()
    vi.unstubAllGlobals()
    handToken(null)
    handLogin(null)
    handFetch(null)
    process.chdir(cwd)
    await rm(away, { recursive: true, force: true })
  })

  it("sends the job's own OIDC token, made out to Vercel's API, as itself, and asks GitHub once while it's good", async () => {
    const api = fakeMessageboard({ tokens: { [RUN]: 'github:repo:700001' } })
    const { asked, sent, request } = inActions(api)
    vi.stubEnv('VERCEL_ORG_ID', 'team_test')
    // The host's fetch for a login is below it.
    const host = vi.fn(as(api, 'user:u_ada'))
    handFetch(host)
    const team = board({ backend: nodeVercel() })
    const posted = await team.post('ci', 'deploy failed on a1b2c3d')
    expect(await team.me()).toMatchObject({ principal: 'github:repo:700001', kind: 'workflow', handle: 'acme/web' })
    expect(credentialSource()).toBe('GitHub Actions OIDC')
    expect((await team.thread(posted.id)).message.by).toEqual({ actor: 'github:repo:700001', principal: 'github:repo:700001', profile: null })
    expect(asked).toEqual([{ audience: AUDIENCE, authorization: `bearer ${request}` }])
    expect(new Set(sent)).toEqual(new Set([`Bearer ${RUN}`]))
    expect(host).not.toHaveBeenCalled()
  })

  it('sends it only when nothing ahead of it applies: an app\'s login, the deployment\'s token, BOARD_TOKEN, or VERCEL_AUTH_TOKEN', async () => {
    const api = fakeMessageboard({ tokens: { [RUN]: 'github:repo:700001', [DEPLOYMENT]: 'project:prj_pong:production', k7Qe2mXa9vLp: 'user:u_bo' } })
    const { asked } = inActions(api)
    vi.stubEnv('VERCEL_ORG_ID', 'team_test')
    const principal = async () => (await board({ backend: nodeVercel() }).me()).principal

    vi.stubEnv('BOARD_TOKEN', 'k7Qe2mXa9vLp')
    expect([await principal(), credentialSource()]).toEqual(['vercel:user:u_bo', 'BOARD_TOKEN'])
    vi.stubEnv('VERCEL', '1')
    vi.stubEnv('VERCEL_OIDC_TOKEN', DEPLOYMENT)
    expect([await principal(), credentialSource()]).toEqual(['vercel:project:prj_pong:production', 'Vercel OIDC'])
    // The app that runs board's CLI says who it runs as, wherever it runs.
    handToken('user:u_jb')
    expect([await principal(), credentialSource()]).toEqual(['vercel:user:u_jb', 'the token you passed'])
    handToken(null)
    handLogin(async () => 'user:u_ada')
    vi.stubEnv('VERCEL', '')
    vi.stubEnv('VERCEL_OIDC_TOKEN', '')
    vi.stubEnv('BOARD_TOKEN', '')
    expect([await principal(), credentialSource()]).toEqual(['vercel:user:u_ada', 'the Vercel CLI'])
    handLogin(null)
    // A login the workflow sets is its choice, while id-token: write is often there for something else.
    vi.stubEnv('VERCEL_AUTH_TOKEN', 'user:u_ada')
    expect([await principal(), credentialSource()]).toEqual(['vercel:user:u_ada', 'the Vercel CLI'])
    expect(asked).toEqual([])
    vi.stubEnv('VERCEL_AUTH_TOKEN', '')
    expect([await principal(), credentialSource()]).toEqual(['github:repo:700001', 'GitHub Actions OIDC'])
  })

  it("isn't a job that may ask for a token without both of GitHub's variables, and goes as your login", async () => {
    const api = fakeMessageboard({ tokens: { [RUN]: 'github:repo:700001' } })
    const { asked } = inActions(api)
    vi.stubEnv('VERCEL_ORG_ID', 'team_test')
    vi.stubEnv('VERCEL_AUTH_TOKEN', 'user:u_ada')
    for (const missing of ['ACTIONS_ID_TOKEN_REQUEST_URL', 'ACTIONS_ID_TOKEN_REQUEST_TOKEN']) {
      const kept = process.env[missing]
      vi.stubEnv(missing, '')
      expect([(await board({ backend: nodeVercel() }).me()).principal, credentialSource()]).toEqual(['vercel:user:u_ada', 'the Vercel CLI'])
      vi.stubEnv(missing, kept!)
    }
    expect(asked).toEqual([])
  })

  it('says how to name the team when nothing does, since its token names none, and asks the API nothing', async () => {
    const api = fakeMessageboard({ tokens: { [RUN]: 'github:repo:700001' } })
    const { sent } = inActions(api)
    await expect(board({ backend: nodeVercel() }).post('ci', 'deploy failed')).rejects.toMatchObject({
      status: 400,
      code: 'missing_team',
      origin: 'handle',
      message: "A GitHub Actions token names no Vercel team, so there's no team's board to use.",
      hint: 'Pass --scope <team ID>, or set VERCEL_ORG_ID.',
    })
    expect(sent).toEqual([])
    // A team named in code, or in the environment, is the board's.
    expect((await board({ team: 'team_test', backend: nodeVercel() }).me()).principal).toBe('github:repo:700001')
    vi.stubEnv('VERCEL_ORG_ID', 'team_test')
    expect((await board({ backend: nodeVercel() }).me()).principal).toBe('github:repo:700001')
  })

  it('holds only the requests it sends the token with to a team: a board({ fetch }) with credentials of its own uses their default team', async () => {
    const api = fakeMessageboard({ tokens: { [RUN]: 'github:repo:700001' } })
    const { asked } = inActions(api)
    const own = vi.fn(as(api, 'user:u_ada'))
    await expect(board({ backend: nodeVercel({ fetch: own }) }).me()).resolves.toMatchObject({ principal: 'vercel:user:u_ada' })
    expect(own).toHaveBeenCalled()
    expect(asked).toEqual([])
  })

  it("never sends the job's token anywhere but Vercel's API, and never asks GitHub for one to send there", async () => {
    const api = fakeMessageboard({ tokens: { [RUN]: 'github:repo:700001' } })
    const { asked, sent } = inActions(api)
    vi.stubEnv('VERCEL_ORG_ID', 'team_test')
    await expect(board({ backend: nodeVercel({ api: 'https://api.example.com' }) }).post('ci', 'deploy failed')).rejects.toMatchObject({
      status: 400,
      code: 'wrong_audience',
      origin: 'handle',
    })
    expect(asked).toEqual([])
    expect(sent).toEqual([])
  })

  it("says why GitHub gave no token, as the handle's own error, not that Vercel's API didn't answer", async () => {
    const api = fakeMessageboard({ tokens: { [RUN]: 'github:repo:700001' } })
    const { sent } = inActions(api, () => Response.json({ message: 'Unable to get ACTIONS_ID_TOKEN_REQUEST_URL env variable' }, { status: 403 }))
    vi.stubEnv('VERCEL_ORG_ID', 'team_test')
    await expect(board({ backend: nodeVercel() }).post('ci', 'deploy failed')).rejects.toMatchObject({
      code: 'no_token',
      origin: 'handle',
      message: 'GitHub Actions refused an OIDC token (403).',
      hint: 'Give the job `permissions: id-token: write`.',
    })
    expect(sent).toEqual([])
  })
})

describe("workflows Vercel's API names", () => {
  const SUBJECT = 'project_path:acme/api:ref_type:branch:ref:main'
  const callers = {
    run: { principal: 'github:repo:700001', kind: 'workflow', handle: 'acme/web' },
    issuer: { principal: `oidc:gitlab.com:${SUBJECT}`, kind: 'workflow', handle: SUBJECT },
  } as const
  const handleOn = (api: ReturnType<typeof fakeMessageboard>, principal: string) => board({ backend: vercel({ team: 'team_test', api: API, fetch: as(api, principal) }) })

  it('shows a GitHub Actions run by its repository and another issuer\'s caller by its subject, as what they wrote and as themselves', async () => {
    const api = fakeMessageboard()
    for (const { principal, kind, handle } of Object.values(callers)) {
      const caller = handleOn(api, principal)
      const posted = await caller.post('ci', `from ${handle}`)
      expect(await caller.me()).toMatchObject({ principal, actor: principal, kind, handle })
      // Read back by a person: the author is the workflow, by the ID the API gave it.
      const { message: read } = await handleOn(api, 'user:u_jb').thread(posted.id)
      expect(read).toMatchObject({ by: { actor: principal, principal, profile: null }, author: { kind, handle } })
    }
    expect((await handleOn(api, 'user:u_jb').channel('ci').messages()).messages.map((message) => [message.by.actor, message.author?.handle])).toEqual([
      [callers.run.principal, 'acme/web'],
      [callers.issuer.principal, SUBJECT],
    ])
  })

  it('shows an agent of a workflow by its profile, through the workflow', async () => {
    const api = fakeMessageboard()
    for (const { principal, handle } of Object.values(callers)) {
      const posted = await handleOn(api, principal).as('ci').post('ci', 'from its agent')
      expect((await handleOn(api, 'user:u_jb').thread(posted.id)).message).toMatchObject({ by: { actor: `${principal}+ci`, principal, profile: 'ci' }, author: { kind: 'agent', handle: 'ci', via: { name: handle, environment: null } } })
    }
  })

  it("finds a mention of a run, or of its agent, by the repository the API names it by", async () => {
    const api = fakeMessageboard()
    await handleOn(api, callers.run.principal).post('ci', 'deploy failed')
    await handleOn(api, callers.run.principal).as('ci').post('ci', 'retrying')
    const person = handleOn(api, 'user:u_jb')
    const { cursor } = await person.poll({ channel: 'ci' })
    await person.post('ci', `@[${callers.run.principal}] what broke?`)
    await person.post('ci', `@[${callers.run.principal}+ci] try again`)
    await person.post('ci', '@[vercel:user:u_ada] not this one')
    const mentioning = async (who: string) => (await handleOn(api, 'user:u_jb').poll({ channel: 'ci', mentions: who, after: cursor })).events.map((event) => event.message?.text)
    expect(await mentioning('acme/web')).toEqual([`@[${callers.run.principal}] what broke?`, `@[${callers.run.principal}+ci] try again`])
    expect(await mentioning(callers.run.principal)).toEqual([`@[${callers.run.principal}] what broke?`, `@[${callers.run.principal}+ci] try again`])
  })

  it("tells a run no grant lets in that it needs one, and makes no board for it", async () => {
    const api = fakeMessageboard({ boardId: null })
    await expect(handleOn(api, callers.run.principal).post('ci', 'deploy failed')).rejects.toMatchObject({
      status: 403,
      code: 'board_not_granted',
      origin: 'handle',
      message: "this workflow has no access to the team's board (acme/web).",
      hint: "Grant it: vb grants create --github acme/web --scope team_test --can '*=read,post,react,label'",
    })
    expect(api.requests).not.toContain('POST /boards/default')
  })

  it("quotes a board's name in the grant it suggests, so the command can't run what the name holds", async () => {
    const name = "ops'; rm -rf ~ #"
    const api = fakeMessageboard({ boards: [{ name }] })
    await expect(board({ name, backend: vercel({ team: 'team_test', api: API, fetch: as(api, callers.run.principal) }) }).post('ci', 'deploy failed')).rejects.toMatchObject({
      code: 'board_not_granted',
      hint: `Grant it: vb grants create --github acme/web --name 'ops'\\''; rm -rf ~ #' --scope team_test --can '*=read,post,react,label'`,
    })
  })
})

import { defineTool } from "eve/tools";
import { z } from "zod";
import { ORIGIN, ownToken } from "../lib/identity.ts";

export default defineTool({
  description:
    "The factory's setup, checked now. `steps`: each step the setup page shows (Vercel, GitHub, Slack, Try it) and its tasks, done or not, with the exact commands and links. `repos`: how many are onboarded, and how many more the GitHub app is on (`waiting`). With `repo`, `asked` says where that repo shows when it's onboarded already, or whether the GitHub app is on it (`app`: true, false, or null when that couldn't be told), which your own GitHub access can't tell. Use it whenever someone asks about setting the factory up, and quote its commands as they are.",
  inputSchema: z.object({
    repo: z.string().optional().describe("A repo to ask about, as owner/name: whether it's onboarded, or whether the GitHub app is on it."),
  }),
  async execute({ repo }) {
    // This deployment's own setup page, which runs the checks. Its OIDC token gets the call through
    // Deployment Protection, which trusts a project's calls to its own environment.
    const token = await ownToken();
    const response = await fetch(`${ORIGIN}/api/launcher/steps${repo ? `?repo=${encodeURIComponent(repo)}` : ""}`, {
      headers: token ? { "x-vercel-trusted-oidc-idp-token": token } : {},
      signal: AbortSignal.timeout(30_000),
    });
    const body = await response.text();
    return response.ok ? body : `The setup page's checks answered ${response.status}: ${body.slice(0, 300)}`;
  },
});

import { Clock, CloudOff, FileText, ListTodo, Paperclip, Tag, X } from 'lucide-react'
import { useEffect, useLayoutEffect, useRef, useState } from 'react'
import { ATTACHMENT_BYTES_MAX, ATTACHMENTS_PER_MESSAGE_MAX } from '../../contract/schemas.ts'
import type { ScheduleTiming } from '../../server/index.default.ts'
import { toast } from './chrome.ts'
import { profilesOf, type State } from './store.ts'
import { actorFor, taskIds } from './task.tsx'
import { fieldMenu, LabelEditor, Panel, Suggest, type KnownLabels } from './ui.tsx'
import { fileSize, laterFields, timingWords } from './words.ts'

// Just Chat's composer: one outlined box, the textarea, a quiet toolbar.
// Enter sends, Shift+Enter breaks a line, ⌘B / ⌘I / ⌘E format, lists continue,
// ↑ in an empty box edits your last message, and every place keeps its draft.

const MAX_HEIGHT = 160

const draftKey = (scope: string) => `board.draft:${scope}`
function readDraft(scope: string): string {
  try {
    return sessionStorage.getItem(draftKey(scope)) ?? ''
  } catch {
    return ''
  }
}
function writeDraft(scope: string, text: string) {
  try {
    if (text) sessionStorage.setItem(draftKey(scope), text)
    else sessionStorage.removeItem(draftKey(scope))
  } catch {}
}

/** Replaces the selection through the browser, so ⌘Z undoes it. */
function insert(el: HTMLTextAreaElement, start: number, end: number, text: string, caret: [number, number]) {
  el.focus()
  el.setSelectionRange(start, end)
  if (!document.execCommand('insertText', false, text)) el.setRangeText(text, start, end, 'end')
  el.setSelectionRange(caret[0], caret[1])
  el.dispatchEvent(new Event('input', { bubbles: true }))
}

const LIST_ITEM = /^(\s*)([-*]|\d+\.)\s(.*)$/

export type Send = {
  text: string
  noSync: boolean
  channel: string
  labels: Record<string, string>
  files: File[]
  /** Set when the thread starts as a task: what it waits for, and the actor it's for. */
  task?: { needs: string[]; for: string | null }
  /** Set to post it later: when, and how often. */
  later?: ScheduleTiming
}

export function Composer(props: {
  scope: string
  /** `data-composer`, for typing anywhere to land here. */
  role: string
  placeholder: string
  known: KnownLabels
  channels?: string[]
  /** The channel it starts on, where it picks one. */
  channel?: string
  /** Where a new thread can start as a task: the page's state, for who you are and what's open; `always` for a view that only starts tasks. */
  tasks?: { state: State; always?: boolean }
  onSend: (send: Send) => void
  onEditLast?: () => void
}) {
  const [text, setText] = useState(() => readDraft(props.scope))
  const [channel, setChannel] = useState(props.channel ?? '')
  const [task, setTask] = useState(props.tasks?.always ?? false)
  const [needs, setNeeds] = useState('')
  // What a task waits for and who it's for: there when wanted, out of the way until then.
  const [detail, setDetail] = useState(false)
  const [later, setLater] = useState<ScheduleTiming | null>(null)
  const [laterOpen, setLaterOpen] = useState(false)
  const [assignee, setAssignee] = useState('')
  const tasking = props.tasks
  const asTask = tasking !== undefined && task
  const [noSync, setNoSync] = useState(false)
  const [labels, setLabels] = useState<Record<string, string>>({})
  const [labelsOpen, setLabelsOpen] = useState(false)
  const [files, setFiles] = useState<File[]>([])
  const area = useRef<HTMLTextAreaElement>(null)
  const picker = useRef<HTMLInputElement>(null)

  /** Adds files from the picker or a paste, up to what a message can carry. */
  const attach = (added: File[]) => {
    const fitting = added.filter((file) => {
      if (file.size <= ATTACHMENT_BYTES_MAX) return true
      toast(`${file.name} is over ${ATTACHMENT_BYTES_MAX / 1024 / 1024} MB`)
      return false
    })
    setFiles((current) => {
      const next = [...current, ...fitting]
      if (next.length > ATTACHMENTS_PER_MESSAGE_MAX) toast(`a message carries at most ${ATTACHMENTS_PER_MESSAGE_MAX} files`)
      return next.slice(0, ATTACHMENTS_PER_MESSAGE_MAX)
    })
    area.current?.focus()
  }

  useEffect(() => {
    setText(readDraft(props.scope))
    if (!matchMedia('(max-width: 900px)').matches && !props.channels) area.current?.focus({ preventScroll: true })
  }, [props.scope])

  useLayoutEffect(() => {
    const el = area.current!
    el.style.height = 'auto'
    el.style.height = `${Math.min(el.scrollHeight, MAX_HEIGHT)}px`
  }, [text])

  const change = (value: string) => {
    setText(value)
    writeDraft(props.scope, value)
  }

  const target = channel.trim().replace(/^#/, '')
  const canSend = (text.trim().length > 0 || files.length > 0) && (!props.channels || target.length > 0)

  const send = () => {
    if (!text.trim() && files.length === 0) return
    if (props.channels && !target) return toast('pick a channel to post in')
    const me = tasking?.state.me
    props.onSend({
      text: text.trim(),
      noSync,
      channel: target,
      labels,
      files,
      ...(asTask && me ? { task: { needs: taskIds(needs), for: assignee.trim() ? actorFor(me.principal, assignee) : null } } : {}),
      ...(later && !asTask ? { later } : {}),
    })
    setLater(null)
    change('')
    setLabels({})
    setFiles([])
    setNeeds('')
    setAssignee('')
    setDetail(false)
    setTask(props.tasks?.always ?? false)
  }

  const wrap = (el: HTMLTextAreaElement, marker: string) => {
    const { selectionStart: start, selectionEnd: end, value } = el
    const selected = value.slice(start, end)
    insert(el, start, end, `${marker}${selected}${marker}`, [start + marker.length, end + marker.length])
  }

  const onKeyDown = (event: React.KeyboardEvent<HTMLTextAreaElement>) => {
    const el = event.currentTarget
    const mod = event.metaKey || event.ctrlKey
    if (event.key === 'Escape') return el.blur()
    if (mod && !event.shiftKey && ['b', 'i', 'e'].includes(event.key.toLowerCase())) {
      event.preventDefault()
      return wrap(el, { b: '**', i: '_', e: '`' }[event.key.toLowerCase()]!)
    }
    if (event.key === 'ArrowUp' && !el.value && props.onEditLast) {
      event.preventDefault()
      return props.onEditLast()
    }
    if (event.key !== 'Enter' || event.nativeEvent.isComposing) return
    if (mod) {
      event.preventDefault()
      return send()
    }
    if (event.shiftKey) return
    const caret = el.selectionStart
    if (caret === el.selectionEnd) {
      const lineStart = el.value.lastIndexOf('\n', caret - 1) + 1
      const line = el.value.slice(lineStart, caret)
      const item = LIST_ITEM.exec(line)
      if (item) {
        event.preventDefault()
        // An empty item ends the list; otherwise the next one starts.
        if (!item[3]!.trim()) return insert(el, lineStart, caret, '', [lineStart, lineStart])
        const marker = /^\d+\.$/.test(item[2]!) ? `${Number.parseInt(item[2]!, 10) + 1}.` : item[2]!
        const next = `\n${item[1]}${marker} `
        return insert(el, caret, caret, next, [caret + next.length, caret + next.length])
      }
    }
    event.preventDefault()
    send()
  }

  const labelEntries = Object.entries(labels)
  return (
    <div className="composer">
      <div
        className="composer-box"
        onClick={(event) => {
          if ((event.target as HTMLElement).closest('button, input, [role="dialog"]')) return
          area.current?.focus()
        }}
      >
        {props.channels && (
          <Suggest
            className="composer-channel"
            prefix="#"
            value={channel}
            onChange={setChannel}
            items={props.channels}
            placeholder="channel"
            label={(item) => (
              <>
                <span className="faint">#</span>
                {item}
              </>
            )}
            onEnter={() => area.current?.focus()}
          />
        )}
        {asTask && (detail || needs.trim() !== '' || assignee.trim() !== '') && (
          <div className="composer-task">
            <label className="suggest grow" title="the tasks this one waits for, by their IDs">
              <span className="prefix">needs</span>
              <input value={needs} onChange={(event) => setNeeds(event.target.value)} placeholder="task IDs it waits for" spellCheck={false} />
            </label>
            <Suggest className="grow" prefix="for" value={assignee} onChange={setAssignee} items={profilesOf(tasking.state, tasking.state.me?.principal ?? '')} placeholder="anyone, or one of your profiles" onEnter={() => area.current?.focus()} />
          </div>
        )}
        {labelEntries.length > 0 && (
          <div className="chips composer-labels">
            {labelEntries.map(([key, value]) => (
              <span key={key} className="label">
                {key}={value}
                <button
                  title={`remove ${key}`}
                  onClick={() =>
                    setLabels((current) => {
                      const next = { ...current }
                      delete next[key]
                      return next
                    })
                  }
                >
                  <X size={11} />
                </button>
              </span>
            ))}
          </div>
        )}
        <textarea
          ref={area}
          data-composer={props.role}
          rows={2}
          maxLength={10_000}
          value={text}
          placeholder={props.placeholder}
          onChange={(event) => change(event.target.value)}
          onKeyDown={onKeyDown}
          onPaste={(event) => {
            const pasted = [...event.clipboardData.files]
            if (pasted.length === 0) return
            event.preventDefault()
            attach(pasted)
          }}
        />
        {files.length > 0 && (
          <div className="chips composer-files">
            {files.map((file, i) => (
              <span key={i} className="file">
                <FileText size={14} strokeWidth={1.75} />
                <span className="file-name">{file.name}</span>
                <span className="faint">{fileSize(file.size)}</span>
                <button title={`remove ${file.name}`} onClick={() => setFiles((current) => current.filter((_, j) => j !== i))}>
                  <X size={11} />
                </button>
              </span>
            ))}
          </div>
        )}
        <div className="composer-footer">
          <button className="tool" title="attach files (or paste them)" onClick={() => picker.current?.click()}>
            <Paperclip size={14} />
          </button>
          <input
            ref={picker}
            type="file"
            multiple
            hidden
            onChange={(event) => {
              attach([...(event.target.files ?? [])])
              event.target.value = ''
            }}
          />
          <Panel
            title="labels"
            trigger={
              <>
                <Tag size={14} />
                {labelEntries.length > 0 && <span className="count">{labelEntries.length}</span>}
              </>
            }
            triggerTitle="labels for this message"
            align="start"
            open={labelsOpen}
            onOpenChange={setLabelsOpen}
          >
            <LabelEditor
              labels={labels}
              known={props.known}
              onSet={(key, value) => setLabels((current) => ({ ...current, [key]: value }))}
              onUnset={(key) =>
                setLabels((current) => {
                  const next = { ...current }
                  delete next[key]
                  return next
                })
              }
            />
          </Panel>
          <button
            className={`tool${noSync ? ' on' : ''}`}
            aria-pressed={noSync}
            title={noSync ? 'board only: this message stays off Slack and GitHub' : 'syncs to Slack and GitHub (click to keep it on the board)'}
            onClick={() => setNoSync(!noSync)}
          >
            <CloudOff size={14} />
            {noSync && <span className="tool-label">board only</span>}
          </button>
          {tasking && !tasking.always && (
            <button
              className={`tool${task ? ' on' : ''}`}
              aria-pressed={task}
              title={task ? 'starts as a task: a thread with a state, for agents to claim (click for a plain thread)' : 'start it as a task'}
              onClick={() => {
                setTask(!task)
              }}
            >
              <ListTodo size={14} />
              {task && <span className="tool-label">task</span>}
            </button>
          )}
          {asTask && (
            <button className={`tool${detail ? ' on' : ''}`} aria-pressed={detail} title="what it waits for, and who it's for" onClick={() => setDetail(!detail)}>
              <span className="tool-label">needs, for</span>
            </button>
          )}
          {!asTask && (
            <Panel
              title="send later"
              trigger={
                <>
                  <Clock size={14} />
                  {later && <span className="tool-label">{timingWords(later)}</span>}
                </>
              }
              triggerClass={`tool${later ? ' on' : ''}`}
              align="start"
              open={laterOpen}
              onOpenChange={setLaterOpen}
            >
              <Later
                value={later}
                onSet={(next) => {
                  setLater(next)
                  setLaterOpen(false)
                  area.current?.focus()
                }}
              />
            </Panel>
          )}
          <span className="hint">enter to send · shift+enter for a new line</span>
          <button className="send" disabled={!canSend} onMouseDown={(event) => event.preventDefault()} onClick={send}>
            {asTask ? 'start task' : later ? 'schedule' : 'send'}
          </button>
        </div>
      </div>
    </div>
  )
}

/** When a message goes out: in a while or at a time, and again every so often. The board checks it. */
function Later({ value, onSet }: { value: ScheduleTiming | null; onSet: (timing: ScheduleTiming | null) => void }) {
  const start = laterFields(value)
  const [after, setAfter] = useState(start.after)
  const [at, setAt] = useState(start.at)
  const [every, setEvery] = useState(start.every)
  const [times, setTimes] = useState(start.times)
  const set = () =>
    onSet({
      ...(after.trim() ? { in: after.trim() } : at ? { at: new Date(at).toISOString() } : {}),
      ...(every.trim() ? { every: every.trim() } : {}),
      ...(every.trim() && Number(times) > 0 ? { times: Number(times) } : {}),
    })
  const ready = after.trim() !== '' || at !== '' || every.trim() !== ''
  return (
    <form
      className="ask"
      onSubmit={(event) => {
        event.preventDefault()
        if (ready) set()
      }}
      {...fieldMenu}
    >
      <div className="label-add">
        <Suggest className="grow" prefix="in" value={after} onChange={setAfter} items={['10m', '1h', '3h', '1d']} placeholder="2h" autoFocus onEnter={() => ready && set()} />
        <span className="faint">or at</span>
        <label className="suggest grow">
          <input type="datetime-local" value={at} disabled={after.trim() !== ''} onChange={(event) => setAt(event.target.value)} />
        </label>
      </div>
      <div className="label-add">
        <Suggest className="grow" prefix="every" value={every} onChange={setEvery} items={['1h', '1d', '7d']} placeholder="never" onEnter={() => ready && set()} />
        <label className="suggest grow" title="stop after this many sends">
          <span className="prefix">times</span>
          <input value={times} disabled={!every.trim()} onChange={(event) => setTimes(event.target.value.replace(/\D/g, ''))} placeholder="no limit" inputMode="numeric" />
        </label>
      </div>
      <div className="label-add end">
        {value && (
          <button type="button" className="clear" onClick={() => onSet(null)}>
            send now instead
          </button>
        )}
        <button type="submit" className="send small" disabled={!ready}>
          set
        </button>
      </div>
    </form>
  )
}

import { createServer } from 'node:http'
import type { AddressInfo } from 'node:net'
import { afterEach, describe, expect, it, vi } from 'vitest'
import { createDiscordAdapter } from '@chat-adapter/discord'
import { createTelegramAdapter } from '@chat-adapter/telegram'
import { createMockState } from '@chat-adapter/tests'
import { chatSdk, channels, type ChatSdkEvent, type ChatSdkOptions } from '../src/sync/chat-sdk.ts'
import type { ReceivedEvent } from '../src/sync/provider.ts'
import type { SyncUnit } from '../src/sync/fn.ts'
import { BOARD_URL, caller, personToken, testBoard } from './harness.ts'

const SECRET = '[REDACTED]'
const GROUP = -1001234567890
const ADA = { id: 42, is_bot: false, first_name: 'Ada', username: 'ada' }
const BOT = { id: 999, is_bot: true, first_name: 'Board', username: 'board_bot' }

type Call = { method: string; body: Record<string, unknown> }

/** Telegram's Bot API, served locally: answers what the adapter asks, and records each call. */
async function botApi() {
  const calls: Call[] = []
  let next = 500
  const server = createServer(async (request, response) => {
    const chunks: Buffer[] = []
    for await (const chunk of request) chunks.push(chunk as Buffer)
    const text = Buffer.concat(chunks).toString('utf8')
    const body = text && request.headers['content-type']?.includes('json') ? JSON.parse(text) as Record<string, unknown> : {}
    const method = request.url!.slice(request.url!.lastIndexOf('/') + 1)
    calls.push({ method, body })
    const result = method === 'getMe' ? BOT
      : method.startsWith('send') ? { message_id: ++next, date: 1735689600, chat: { id: Number(body.chat_id), type: 'supergroup' }, from: BOT, text: textOf(body) }
      : true
    response.setHeader('content-type', 'application/json')
    response.end(JSON.stringify({ ok: true, result }))
  })
  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve))
  servers.push(server)
  /** The messages sent to Telegram, plain or rich, as the chat and the text. */
  const sent = () => calls.filter((call) => call.method.startsWith('send')).map((call) => ({ chat: String(call.body.chat_id), text: textOf(call.body) }))
  return { url: `http://127.0.0.1:${(server.address() as AddressInfo).port}`, calls, sent }
}
const textOf = (body: Record<string, unknown>) => String(body.text ?? (body.rich_message as { markdown?: string } | undefined)?.markdown ?? '')
const servers: ReturnType<typeof createServer>[] = []
afterEach(async () => {
  await Promise.all(servers.splice(0).map((server) => new Promise((resolve) => server.close(resolve))))
})

/** Telegram's real adapter through `chatSdk()`, on an in-process board. */
async function setup(groups: Record<string, SyncUnit<ChatSdkEvent>>, hooks: Omit<ChatSdkOptions, 'adapter'> = {}) {
  const api = await botApi()
  const adapter = createTelegramAdapter({ botToken: 'test-token', secretToken: SECRET, mode: 'webhook', apiUrl: api.url, userName: 'board_bot' })
  const provider = chatSdk({ adapter, ...hooks }, channels(groups))
  const board = testBoard({ sync: { telegram: provider } })
  let update = 0
  /** An update as Telegram sends it, with the webhook's secret token. The same `id` is a redelivery. */
  const request = (payload: Record<string, unknown>, id = ++update) =>
    new Request(`${BOARD_URL}/webhooks/telegram`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', 'x-telegram-bot-api-secret-token': SECRET },
      body: JSON.stringify({ update_id: id, ...payload }),
    })
  const deliver = (payload: Record<string, unknown>, id?: number) => board.fetch(request(payload, id))
  const say = (messageId: number, text: string) =>
    deliver({ message: { message_id: messageId, date: 1735689600, chat: { id: GROUP, type: 'supergroup', title: 'Support' }, from: ADA, text } })
  const react = (messageId: number, change: { old: string[]; now: string[] }, date: number, id?: number) =>
    deliver({
      message_reaction: {
        chat: { id: GROUP, type: 'supergroup', title: 'Support' }, message_id: messageId, user: ADA, date,
        old_reaction: change.old.map((emoji) => ({ type: 'emoji', emoji })), new_reaction: change.now.map((emoji) => ({ type: 'emoji', emoji })),
      },
    }, id)
  return { api, board, provider, request, deliver, say, react }
}

type Read = { id: number; text: string; from: string | null; reactions: Record<string, string[]>; by: { actor: string } }
const read = async (call: ReturnType<typeof caller>, channel: string) =>
  (await call('GET', `/messages?channel=${channel}`)).body.messages as Read[]

describe('chatSdk() on a real adapter, with no hooks', () => {
  it('mirrors a Telegram group both ways', async () => {
    const { api, board, say } = await setup({ [String(GROUP)]: 'support' })
    const julian = caller(board.fetch, await personToken(), {})

    expect((await say(10, 'export is broken')).status).toBe(200)
    await vi.waitFor(async () => expect(await read(julian, 'support')).toHaveLength(1))
    const [root] = await read(julian, 'support')
    expect(root).toMatchObject({ text: 'export is broken', from: 'telegram', by: { actor: `telegram:user:${ADA.id}` } })

    await julian('POST', '/messages', { re: root!.id, text: 'looking into it' })
    await vi.waitFor(() => expect(api.sent()).toHaveLength(1))
    expect(api.sent()).toEqual([{ chat: String(GROUP), text: expect.stringMatching(/julian.*looking into it/) }])
  })

  it('keeps a new board root on the board, since a group is one conversation', async () => {
    const { api, board } = await setup({ [String(GROUP)]: 'support' })
    const julian = caller(board.fetch, await personToken(), {})
    const { body } = await julian('POST', '/messages', { channel: 'support', text: 'board only' })

    const attach = await julian('POST', `/messages/${body.message.id}/sync`, { target: `telegram:${GROUP}` })
    expect(attach.status).toBe(400)
    expect(api.sent()).toEqual([])
  })

  it('knows a reaction by its webhook: a redelivery is the same reaction, a re-add is another', async () => {
    const { board, say, react } = await setup({ [String(GROUP)]: 'support' })
    const julian = caller(board.fetch, await personToken())
    await say(10, 'export is broken')
    await vi.waitFor(async () => expect(await read(julian, 'support')).toHaveLength(1))

    await react(10, { old: [], now: ['👍'] }, 1735689700, 100)
    await react(10, { old: [], now: ['👍'] }, 1735689700, 100) // Telegram retries it
    await react(10, { old: ['👍'], now: [] }, 1735689760)
    await react(10, { old: [], now: ['👍'] }, 1735689820) // Ada adds it again
    // Each delivery is stored before its webhook answers.
    const { body: inbox } = await julian('GET', '/inbox/telegram')
    const reactions = (inbox.events as { event: { kind: string; added: boolean } }[]).filter((record) => record.event.kind === 'reaction')
    // Two adds and a remove, in whatever order the inbox lists them.
    expect(reactions.map((record) => record.event.added).sort()).toEqual([false, true, true])
    await vi.waitFor(async () => expect((await read(julian, 'support'))[0]!.reactions).toEqual({ thumbs_up: [`telegram:user:${ADA.id}`] }))
  })

  it("lets Telegram's retry through when the board couldn't store the first delivery", async () => {
    const { provider, request } = await setup({ [String(GROUP)]: 'support' })
    const update = { message: { message_id: 10, date: 1735689600, chat: { id: GROUP, type: 'supergroup' }, from: ADA, text: 'export is broken' } }
    const stored: ReceivedEvent[] = []
    let attempts = 0
    const emit = async (received: ReceivedEvent) => {
      if (++attempts === 1) throw new Error('the board is down')
      stored.push(received)
    }

    await expect(provider.receive('telegram', request(update, 7), emit)).rejects.toThrow('the board is down')
    expect((await provider.receive('telegram', request(update, 7), emit)).status).toBe(200)
    expect(stored.map((received) => received.event.kind)).toEqual(['message'])
  })
})

describe('chatSdk() on Discord, whose reactions carry no ID', () => {
  it('keeps add, remove, and add apart, and stores each before the webhook answers', async () => {
    const adapter = createDiscordAdapter({ botToken: '[REDACTED]', publicKey: 'ab'.repeat(32), applicationId: '999' })
    const board = testBoard({ sync: { discord: chatSdk({ adapter }, channels({ 'G1:C1': 'support' })) } })
    const julian = caller(board.fetch, await personToken())
    // What Discord says about the reaction is the same each time; the gateway listener adds when it saw it.
    const data = { user_id: '42', channel_id: 'C1', message_id: 'M1', guild_id: 'G1', channel_type: 0, emoji: { id: null, name: '👍' }, user: { id: '42', username: 'ada' } }
    const forward = (type: 'ADD' | 'REMOVE', timestamp: number) =>
      board.fetch(new Request(`${BOARD_URL}/webhooks/discord`, {
        method: 'POST',
        headers: { 'content-type': 'application/json', 'x-discord-gateway-token': '[REDACTED]' },
        body: JSON.stringify({ type: `GATEWAY_MESSAGE_REACTION_${type}`, timestamp, data }),
      }))

    for (const [type, timestamp] of [['ADD', 1735689600000], ['REMOVE', 1735689660000], ['ADD', 1735689720000], ['ADD', 1735689720000]] as const) {
      expect((await forward(type, timestamp)).status).toBe(200)
    }
    // The last is the one before it, delivered again.
    const { body: inbox } = await julian('GET', '/inbox/discord')
    const reactions = (inbox.events as { event: { kind: string; added: boolean } }[]).filter((record) => record.event.kind === 'reaction')
    // Two adds and a remove, in whatever order the inbox lists them.
    expect(reactions.map((record) => record.event.added).sort()).toEqual([false, true, true])
  })

  it("answers a forwarded reaction only once the board has stored it, though the adapter doesn't wait", async () => {
    const adapter = createDiscordAdapter({ botToken: '[REDACTED]', publicKey: 'ab'.repeat(32), applicationId: '999' })
    const provider = chatSdk({ adapter }, channels({ 'G1:C1': 'support' }))
    const stored: ReceivedEvent[] = []
    // A board that takes a moment to store what came in.
    const emit = async (received: ReceivedEvent) => {
      await new Promise((resolve) => setTimeout(resolve, 50))
      stored.push(received)
    }
    const data = { user_id: '42', channel_id: 'C1', message_id: 'M1', guild_id: 'G1', channel_type: 0, emoji: { id: null, name: '👍' }, user: { id: '42', username: 'ada' } }
    const response = await provider.receive('discord', new Request(`${BOARD_URL}/webhooks/discord`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', 'x-discord-gateway-token': '[REDACTED]' },
      body: JSON.stringify({ type: 'GATEWAY_MESSAGE_REACTION_ADD', timestamp: 1735689600000, data }),
    }), emit)
    expect(response.status).toBe(200)
    expect(stored.map((received) => received.event.kind)).toEqual(['reaction'])
  })
})

